    # number of lines: if ends with newline, split gives trailing empty string
    n_split = len(lines) if not ends_with_newline else len(lines) - 1
    blank = 0
    for l in lines[:n_split]:
        if l.strip() == "":
            blank += 1
    out[f] = {
        "ends_with_newline": ends_with_newline,
        "wc_l": n_split,
        "split_count": len(lines),
        "blank_lines": blank,
        "content_repr": repr(content)[:400],
    }
return out
